Item.method_code:
string namePattern = @"^[a-zA-Z_0-9-]+$";
string webServiceId = this.getProperty("endpoint_name");

if (!System.Text.RegularExpressions.Regex.IsMatch(webServiceId, namePattern))
{
  throw new InvalidOperationException(CCO.ErrorLookup.Lookup("cws_EndpointNameMustBeValid"));
}

return this;
